"""Fixtures for SANA-WM streaming's carried temporal context, generated by upstream NVlabs/Sana b3bad956 code itself:
- `fused_streaming._cached_temporal_short_conv` (the GDN key short conv: causal forward pass with the previous chunk's last
  K-1 input frames as left context, backward pass isolated in the chunk, minus the centre tap) over chunks of 4, 3 and 3 frames;
- `CachedGLUMBConvTemp` (the FFN: spatial GLUMBConv per frame, then a temporal (3,1) conv reading the previous chunk's
  last frame on the left) over chunks of 4 and 3 frames.
FLA's ShortConvolution runs through Triton, so this needs a CUDA device; the tensors are F32 and saved on the host.

usage: <upstream venv python> -I generate_sana_wm_streaming_cache_fixtures.py <upstream root> <out.safetensors>
"""
import sys

root, out = sys.argv[1], sys.argv[2]
sys.path.insert(0, root)
import torch  # noqa: E402
from fla.modules import ShortConvolution  # noqa: E402
from safetensors.torch import save_file  # noqa: E402
from diffusion.model.ops.fused_streaming import _cached_temporal_short_conv  # noqa: E402
from diffusion.model.nets.basic_modules import CachedGLUMBConvTemp  # noqa: E402

torch.manual_seed(0)
dev = torch.device("cuda")
H, W, C, K = 2, 3, 8, 4
S = H * W
tensors = {}

conv = ShortConvolution(hidden_size=C, kernel_size=K, bias=False, activation=None).to(dev).float()
with torch.no_grad():
    conv.weight.copy_(torch.randn_like(conv.weight) * 0.5)
tensors["tconv.weight"] = conv.weight.detach().cpu()  # [C, 1, K]
cache = None
for i, t in enumerate((4, 3, 3)):
    x = torch.randn(1, t * S, C, device=dev)
    with torch.no_grad():
        y, cache = _cached_temporal_short_conv(x, conv, (t, H, W), cache, save_cache=True)
    tensors[f"tconv.chunk{i}.input"] = x[0].cpu()
    tensors[f"tconv.chunk{i}.output"] = y[0].float().cpu()

hidden = 12
ffn = CachedGLUMBConvTemp(in_features=C, hidden_features=hidden, use_bias=(True, True, False)).to(dev).float().eval()
with torch.no_grad():
    for p in ffn.parameters():
        p.copy_(torch.randn_like(p) * 0.3)
for name, p in ffn.state_dict().items():
    tensors[f"ffn.{name}"] = p.detach().cpu()
kv = [None] * 10
for i, t in enumerate((4, 3)):
    x = torch.randn(1, t * S, C, device=dev)
    with torch.no_grad():
        y, kv = ffn(x, HW=(t, H, W), save_kv_cache=True, kv_cache=kv)
    tensors[f"ffn.chunk{i}.input"] = x[0].cpu()
    tensors[f"ffn.chunk{i}.output"] = y[0].float().cpu()
save_file({k: v.contiguous() for k, v in tensors.items()}, out, metadata={"H": str(H), "W": str(W), "C": str(C), "hidden": str(hidden)})
print("wrote", out, sorted(tensors))
